import './ProgressIndicator.css';
import type { DevelopPhaseInfo } from './types';

interface ProgressIndicatorProps {
  phases: DevelopPhaseInfo[];
}

export function ProgressIndicator({ phases }: ProgressIndicatorProps) {
  return (
    <div className="progress-indicator">
      {phases.map((phase, index) => (
        <div key={phase.id} className={`phase-item ${phase.status}`}>
          <span className="phase-icon">
            {phase.status === 'completed' ? '✅' : phase.icon}
          </span>
          <span className="phase-label">{phase.label}</span>
          {index < phases.length - 1 && (
            <div
              className={`phase-connector ${phase.status === 'completed' ? 'completed' : 'pending'}`}
            />
          )}
        </div>
      ))}
    </div>
  );
}

.progress-indicator {
  display: flex;
  align-items: center;
  padding: var(--engin-space-sm) var(--engin-space-md);
  background: var(--engin-bg-secondary);
  border-bottom: 1px solid var(--engin-border);
  overflow-x: auto;
  gap: var(--engin-space-xs);
  flex-shrink: 0;
}

.phase-item {
  display: flex;
  align-items: center;
  gap: var(--engin-space-xs);
  white-space: nowrap;
  font-size: 12px;
}

.phase-icon {
  font-size: 14px;
  line-height: 1;
}

.phase-label {
  font-size: 12px;
  line-height: 1;
}

/* ── Status: completed ──────────────────────────────────────────────────── */

.phase-item.completed .phase-icon {
  color: var(--engin-success);
}

.phase-item.completed .phase-label {
  color: var(--engin-text-muted);
}

/* ── Status: active ─────────────────────────────────────────────────────── */

.phase-item.active .phase-icon {
  color: var(--engin-accent);
}

.phase-item.active .phase-label {
  color: var(--engin-accent);
  font-weight: 700;
}

.phase-item.active {
  background: var(--engin-bg-hover);
  border-radius: var(--engin-radius-sm);
  padding: 2px 4px;
}

/* ── Status: pending ────────────────────────────────────────────────────── */

.phase-item.pending .phase-icon {
  opacity: 0.4;
}

.phase-item.pending .phase-label {
  color: var(--engin-text-muted);
}

/* ── Connector ──────────────────────────────────────────────────────────── */

.phase-connector {
  width: 20px;
  height: 1px;
  flex-shrink: 0;
}

.phase-connector.completed {
  background: var(--engin-success);
}

.phase-connector.pending {
  background: var(--engin-border);
}

